+            exclusionExpression.add(randomAlphaOfLengthBetween(0, 5));
+        }
+        exclusionExpression.add(exclusion);
+        for (int i = 0; i < randomIntBetween(0, 3); i++) {
+            exclusionExpression.add(randomAlphaOfLengthBetween(0, 5));
