+    private static void writeRandomly(OutputStream stream, byte[] bytes) throws IOException {
+        for (var pos = 0; pos < bytes.length;) {
+            if (randomBoolean()) {
+                stream.write(bytes[pos++]);
+            } else {
+                var len = between(1, bytes.length - pos);
+                stream.write(bytes, pos, len);
+                pos += len;
+            }
+        }
+    }
