+        for (int i = 0; i < boundary.numPoints(); i++) {
+            minLat = Math.min(minLat, boundary.getLatLon(i).getLatRad());
+        }
+        boundingBox.topLeft().reset(90, -180d);
+        boundingBox.bottomRight().reset(Math.toDegrees(minLat), 180d);
