+        testFromInvalid("");
+        testFromInvalid("not-a-valid-timestamp");
+        testFromInvalid("2023-17-42");
+    }
+
+    private void testFromInvalid(String from) {
+        final RestStartTransformAction handler = new RestStartTransformAction();
